import datetime,hashlib,json,re
from pathlib import Path
from urllib.parse import urlsplit,urlunsplit

ROOT=Path(__file__).resolve().parents[2]
OUT=Path(__file__).resolve().parent
NA='unavailable'
LANE='chemokine_expansion'
START='2026-09-13 14:48:48 UTC'
END='2026-09-13 17:43:03 UTC'
def write(name,obj):
    (OUT/name).write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def snap(name):return 'research/chemokine_expansion/snapshots/'+name

sources=[]
def source(i,title,authors,year,url,doi,pmid,access,file,notes,ingestion='extracted'):
    retrieval=json.loads((OUT/'snapshots'/file).read_text()).get('retrieved_at',{})
    when=retrieval.get('current_time',NA) if isinstance(retrieval,dict) else retrieval
    d=dict(source_id=f'XCH_S{i:03}',title=title,authors=authors,year=year,url=url,doi=doi,pmid=pmid,source_type='primary_study',version='published_article; exact source revision unavailable',retrieved_at=when,access_level=access,snapshot_path=snap(file),species='Homo sapiens',notes=notes,ingestion_status=ingestion)
    sources.append(d);return d['source_id']

S1=source(1,'Chemokine receptor usage by human eosinophils. The importance of CCR3 demonstrated using an antagonistic monoclonal antibody.','H Heath; S Qin; P Rao; L Wu; G LaRosa; N Kassam; PD Ponath; CR Mackay',1997,'https://pubmed.ncbi.nlm.nih.gov/9005985/','10.1172/JCI119145','9005985','abstract_and_primary_methods_excerpts','search3.json','Complete indexed PubMed abstract plus an indexed publisher PDF methods excerpt were inspected. The PDF open response in open3.json reports its existence but does not contain a complete inspected article. Primary human eosinophil results only; mouse L1.2 receptor-transfectant experiments are not imported.')
