S8=source(8,'Chemokine receptor specific for IP10 and mig: structure, function, and expression in activated T-lymphocytes.','M Loetscher; B Gerber; P Loetscher; SA Jones; L Piali; I Clark-Lewis; M Baggiolini; B Moser',1996,'https://rupress.org/jem/article/184/3/963/50973/Chemokine-receptor-specific-for-IP10-and-mig','10.1084/jem.184.3.963',NA,'abstract','search2.json','CXCL10 candidate only. Abstract describes a cloned human receptor and calcium/chemotaxis responses, but does not resolve the host for each functional experiment. No primary-human CXCL10 functional assertion is extracted from this abstract.','await_full_text')

cohorts=[]
def cohort(i,source_id,participants,tissue,cell,state,disease,intervention,donors=NA,samples=NA,parent=NA,notes='Donor overlap with other reports unavailable; do not count as independent replication.'):
    cid=f'XCH_CO{i:03}'
    cohorts.append(dict(cohort_id=cid,dataset_id=NA,accession=NA,study_id=source_id,participants=participants,ancestry=NA,species='Homo sapiens',tissue=tissue,cell_type=cell,disease=disease,intervention=intervention,sample_count=samples,donor_count=donors,parent_cohort=parent,related_publications=[source_id],independence_status='unresolved',notes=notes+' Cell state: '+state))
    return cid
C1=cohort(1,S1,'Human eosinophil donors; abstract includes allergic and eosinophilic individuals','peripheral blood','eosinophil','Fresh and IL5-primed conditions are discussed; exact condition per extracted response unavailable','allergic/eosinophilic and other donor groups; unresolved separation','Recombinant chemokines with anti-CCR3 7B11',notes='Same donor pool reused across ligand/readout assertions. The number tested for each functional experiment was not extracted; transfectant data excluded.')
C2=cohort(2,S2,'Healthy human subjects','peripheral blood','eosinophil','IL5-primed','healthy','Recombinant eotaxins; anti-CCR3 antibody',samples='Four independent experiments for the 18-h comparison; donor count not equated to experiments')
