FIELDS='species ancestry age sex tissue disease disease_severity treatment_status cell_type cell_state developmental_state stimulation dose duration assay genomic_background time_point effect_size effect_unit uncertainty causal_directness limitations contradiction_group candidate_path'.split()
assertions=[]
def assertion(i,chem,co,source_id,obj,predicate,summary,locator,tier='P2',direction='increase',measurement='cellular_phenotype',reviewed=False,**extra):
    ctx=next(c for c in cohorts if c['cohort_id']==co)
    a={k:NA for k in FIELDS}
    a.update(assertion_id=f'XCH_A{i:03}',subject=chem,subject_type='protein',subject_layer='P',subject_species='Homo sapiens',object=obj,object_type='cellular_phenotype' if measurement=='cellular_phenotype' else 'protein',object_layer='F' if measurement=='cellular_phenotype' else 'P',object_species='Homo sapiens',predicate=predicate,measurement=measurement,direction=direction,source_id=source_id,cohort_id=co,evidence_tier=tier,evidence_summary=summary,source_locator=locator,species='Homo sapiens',tissue=ctx['tissue'],cell_type=ctx['cell_type'],disease=ctx['disease'],qc_status='reviewed_extraction' if reviewed else 'needs_full_text',qualitative_confidence='moderate' if reviewed else 'low',causal_directness='Ligand-response experiment limited to the stated cells and assay; receptor identity not assigned without direct blockade.',limitations='Full methods and donor-level precision were not recovered; no in vivo or cross-context generalization.')
    a.update(extra)
    a['scoring_annotation']={'tested_hypothesis':f'{chem} affects {obj} in the explicitly recorded context of {a["assertion_id"]}', 'evidence_relation':'inconclusive' if direction=='null' else 'supports','null_adequacy':NA,'rationale':'Nonsignificant/undetected response is not equivalence or evidence of biological absence.' if direction=='null' else 'Supports only the stated directly reported response; full-text and independent review gates remain applicable.'}
    assertions.append(a);return a

