assertion(2,'CCL11',C1,S1,'eosinophil intracellular calcium mobilization','induces_calcium_flux_blocked_by_CCR3_antibody','Anti-CCR3 pretreatment inhibited the eosinophil calcium response to eotaxin.','PubMed abstract: pretreatment/calcium-flux sentence; search3.json.',tier='P3',stimulation='CCL11 with or without anti-CCR3 7B11',assay='Intracellular calcium flux; full ligand-specific protocol unavailable',causal_directness='CCR3 antagonist-sensitive proximal response; no downstream transcription inferred.')
assertion(3,'CCL13',C1,S1,'eosinophil chemotaxis','induces_chemotaxis_blocked_by_CCR3_antibody','MCP4-induced eosinophil chemotaxis was inhibited by CCR3 blockade.','PubMed abstract: all CCR3-ligand chemotaxis sentence and named MCP4 response sentence; search3.json.',tier='P3',stimulation='CCL13 with or without anti-CCR3 7B11',assay='ECV304 transendothelial migration assay with migrated-cell flow counts',limitations='Same donor pool as CCL11 observations. CCR3 dependence in eosinophils does not exclude CCR2-mediated CCL13 responses in other cellular systems.')
assertion(4,'CCL13',C1,S1,'eosinophil intracellular calcium mobilization','induces_calcium_flux_blocked_by_CCR3_antibody','The MCP4 eosinophil calcium response was sensitive to anti-CCR3 pretreatment.','PubMed abstract: all-ligand calcium-flux and named MCP4 sentences; search3.json.',tier='P3',stimulation='CCL13 with or without anti-CCR3 7B11',assay='Intracellular calcium flux; full ligand-specific protocol unavailable',limitations='CCR3 dependence is cell-specific. Distinct CCR2/CCR3 transfectant results in candidate Garcia-Zepeda 1996 await full-text extraction.')
assertion(5,'CCL26',C2,S2,'healthy-donor eosinophil migration','induces_migration_sensitive_to_CCR3_blockade','CCL26-induced migration in healthy-donor eosinophils was blocked by anti-CCR3.','Publisher Figure 5 discussion and PubMed abstract healthy-subject blockade sentence; search3.json and search1.json.',tier='P3',cell_state='IL5-primed',stimulation='CCL26 after IL5 priming; anti-CCR3 comparison',dose='100 nM CCL26; 10 ng/mL IL5 priming for 15 min',duration='18 h migration',time_point='18 h',assay='In vitro migration apparatus; complete setup not inspected',limitations='Healthy comparison uses four independent experiments, not an established four-donor cohort. Antibody concentration and per-panel donor overlap unavailable.')
assertion(6,'CCL26',C3,S2,'asthma-donor eosinophil migration','induces_biphasic_migration','Asthmatic-donor eosinophils showed early and delayed migration phases with CCL26.','PubMed abstract 0–6 h/12–18 h sentences; publisher late-phase Results excerpt; search1.json and search3.json.',cell_state='IL5-primed',stimulation='CCL26 after IL5 priming',dose='100 nM CCL26; 10 ng/mL IL5 priming for 15 min',duration='18 h observation',time_point='early 0–6 h and delayed 12–18 h',assay='In vitro migration kinetics',limitations='Temporal pattern is an observed phenotype, not a temporal prior or a newly identified receptor. Comparison-caption experiment counts are not substituted for kinetic-panel donor counts.')
assertion(7,'CCL26',C3,S2,'late asthma-donor eosinophil migration','late_phase_not_detectably_inhibited_by_CCR3_antibody','Anti-CCR3 did not inhibit the reported delayed CCL26 migration phase in asthma donors.','Publisher Results heading: CCR3 blockade does not inhibit the late phase; PubMed abstract; search3.json and search1.json.',direction='null',cell_state='IL5-primed',stimulation='CCL26 with anti-CCR3 antibody',dose='100 nM CCL26; antibody concentration unavailable',duration='12–18 h late phase within 18-h assay',time_point='12–18 h',assay='In vitro migration kinetics with receptor-blocking antibody',causal_directness='An antagonist-insensitive component was observed; neither complete absence of CCR3 contribution nor a named alternative receptor is established.',limitations='No equivalence margin, confidence interval or blockade-efficiency estimate extracted. Antagonist selectivity limitations are reported for other tested small molecules.',contradiction_group='XCH_CCL26_CCR3_CONTEXT')
assertions[-1]['scoring_annotation']['tested_hypothesis']='CCR3 antibody blockade modifies CCL26-induced late migration in the specified asthma-donor eosinophil context'
assertion(8,'CCL22',C4,S3,'monocyte-derived dendritic-cell migration','induces_migration','Human monocyte-derived dendritic cells migrated to MDC in microchamber assays.','Indexed PubMed abstract: microchamber migration sentence; search3.json.',dose='Maximal response reported at 1 ng/mL CCL22',assay='Microchamber migration assay',cell_state='differentiated monocyte-derived dendritic cells; maturation conditions unavailable',limitations='Receptor dependence is not established by this excerpt. Cell preparation, donor count, migration time and uncertainty unavailable.')
a=assertion(9,'CCL22',C5,S4,'CCL22','protein_localizes_in_inflamed_skin_dendritic_cells','CCL22 protein was localized within CD1a-positive or CD83-positive dermal dendritic cells.','Results Immunohistochemical Localization and Figure 7 B–D legend; open1.json lines 187–191 and 223–225.',tier='P1',direction='association',measurement='protein_abundance',reviewed=True,assay='Double immunostaining and immunoelectron microscopy',cell_state='in situ dendritic cells in infected inflamed skin-flap dermis',stimulation='Candida-associated tissue inflammation; no experimental cytokine treatment',time_point='Skin-flap biopsies approximately two years after primary surgery',causal_directness='Observational protein localization; extracellular secretion and T-cell recruitment were not directly measured.',limitations='Immunoelectron microscopy subset counts differ between Methods and legend. Localization in secretory compartments is not a secretion-rate assay.')
a.update(subject='CD1a-positive or CD83-positive dermal dendritic cell',subject_type='cell',subject_layer='C')
