assertion(10,'CCL17',C8,S7,'Hut78 T-cell lymphoma-cell chemotaxis','induces_dose_dependent_chemotaxis','Hut78 cells migrated toward soluble CCL17 with a bell-shaped concentration response.','Results first subsection, first paragraph and Figure 1A reference; open3.json.',cell_state='Endogenous CCR4-positive human lymphoma line',assay='Chemotaxis assay; detailed protocol not inspected',limitations='Hut78 is a human cancer cell line, not primary Th2 cells. No antagonist dependence or donor transportability imported from other experiments.')
assertion(11,'CCL22',C8,S7,'Hut78 T-cell lymphoma-cell chemotaxis','induces_dose_dependent_chemotaxis','Hut78 cells also migrated toward soluble CCL22.','Results first subsection, first paragraph and Figure 1A reference; open3.json.',cell_state='Endogenous CCR4-positive human lymphoma line',assay='Chemotaxis assay; detailed protocol not inspected',limitations='Same cell-line experiment family as CCL17; not independent replication. Relative potency is not quantified from the excerpt.')
for chem,start,subset in [('CCL3',12,'predominantly CD8-positive'),('CCL4',15,'CD4-positive')]:
    assertion(start,chem,C6,S5,f'{subset} T-cell chemotaxis','induces_migration_in_CD3_activated_T_cells',f'{chem} attracted {subset} T cells in the anti-CD3-activated condition.','PubMed abstract: activation requirement and phenotype-analysis sentences; open3.json.',cell_state='anti-CD3-activated',stimulation=f'Recombinant human {chem} after anti-CD3 activation',assay='T-cell chemotaxis with migrated-cell phenotyping',limitations='Subset tendency is not exclusivity. Activation duration, ligand dose and purification protocol unavailable; purification dependence described in XCH_S006.')
    assertion(start+1,chem,C6,S5,'unstimulated T-cell chemotaxis','no_attraction_reported_in_unstimulated_condition',f'Unstimulated T cells did not show attraction to {chem} under the reported preparation conditions.','PubMed abstract: did not attract unstimulated lymphocytes sentence; open3.json.',direction='null',cell_state='unstimulated comparator; isolation/culture history unavailable',stimulation=f'Recombinant human {chem}; no anti-CD3 stimulation',assay='T-cell chemotaxis',limitations='No equivalence or detection-threshold evidence. A later purification study reports unstimulated-cell responses after rapid isolation, so this is not a universal resting-cell nonresponse.',contradiction_group=f'XCH_{chem}_PREPARATION_CONTEXT')
    assertion(start+2,chem,C7,S6,'rapidly purified unstimulated T-cell chemotaxis','induces_migration_after_rapid_purification_without_CD3',f'Rapidly purified T cells responded to {chem} without anti-CD3 stimulation.','Publisher excerpt: Rapidly purified T cells sentence; open3.json.',cell_state='rapidly purified; no anti-CD3 stimulation',stimulation=f'Recombinant human {chem}',assay='Microchemotaxis assay with extracellular-matrix/purification comparison',limitations='Exact ligand-specific dose, donor count and magnitude unavailable. Prolonged 37-degree incubation reduced mobility in this methods study; no intrinsic activation requirement is inferred.',contradiction_group=f'XCH_{chem}_PREPARATION_CONTEXT')

searches=[]
query_files=[('XCH_Q001','search1.json'),('XCH_Q002','search2.json'),('XCH_Q003','search3.json'),('XCH_Q004','open3.json')]
for qid,fn in query_files:
    data=json.loads((OUT/'snapshots'/fn).read_text());queries=data.get('queries',[])
    if fn=='search1.json':queries=[x.get('q',x) if isinstance(x,dict) else x for x in queries]
    retrieved=data.get('retrieved_at',{});when=retrieved.get('current_time',NA) if isinstance(retrieved,dict) else retrieved
    searches.append(dict(search_id=qid,lane=LANE,query=json.dumps(queries,ensure_ascii=False),database='public web search; primary publisher/PubMed/PMC indexed results',searched_at=when,result_source_ids=[],screening_notes='One batched search with the exact component queries listed. Ranked results are not exhaustive; screening below preserves repeated candidate appearances by query.',snapshot_path=snap(fn)))

# Preserve every returned candidate heading actually screened. Strip query strings
# from citation URLs: signed delivery parameters are not scientific identifiers.
screening=[]
included={s['url']:s['source_id'] for s in sources if s['ingestion_status']=='extracted'}
alias_sources={'https://pmc.ncbi.nlm.nih.gov/articles/PMC2196293/':S3,'https://pubmed.ncbi.nlm.nih.gov/23532518/':S2,'https://pubmed.ncbi.nlm.nih.gov/24563252/':S7}
for qid,fn in query_files:
    text=json.loads((OUT/'snapshots'/fn).read_text())['result']
    matches=re.findall(r'^(.+?) \((https?://[^\n]+)\)$',text,re.M)
    for title,url in matches:
        parsed=urlsplit(url);url=urlunsplit((parsed.scheme,parsed.netloc,parsed.path,'',''))
        sid=included.get(url,alias_sources.get(url))
        host=parsed.netloc.lower()
        if sid:
            s=next(s for s in sources if s['source_id']==sid)
            decision='include' if s['access_level']=='full_text_tool_response' else 'await_full_text'
            reason='Included narrow protein-localization extraction from inspected full text.' if decision=='include' else 'Narrow reported results retained as provisional assertions; full methods/context review remains required.'
        elif any(x in host for x in ('wikipedia.org','patent','rndsystems.com','leinco.com','catalogimages.wiley.com')):
            decision='exclude';reason='Encyclopedia, patent, commercial reagent information or book excerpt; not selected primary experimental evidence.'
        elif any(x in title.lower() for x in ('surrogate antibod','engagement of two distinct binding','chemokines enhance immunity')):
            decision='exclude';reason='Inspected description concerns mouse ligands/mouse chemotaxis or nonhuman in vivo work; not used as primary human functional evidence.'
        elif any(x in title.lower() for x in ('comprehensive review','regulation and modulation','regulation of eosinophil recruitment','eotaxin-1 (ccl11)')):
            decision='exclude';reason='Review/background result; no new primary assertion extracted.'
        else:
            decision='await_full_text';reason='Potentially relevant candidate or contextual method study; full text, assay host and exact ligand-specific primary results not resolved within the bounded retrieval.'
        d=dict(candidate_id=f'XCH_CAN{len(screening)+1:03}',query_id=qid,title=title,url=url,doi=NA,pmid=NA,decision=decision,reason=reason)
        if sid:
            d.update(doi=s['doi'],pmid=s['pmid']);next(q for q in searches if q['search_id']==qid)['result_source_ids'].append(sid)
        elif 'pubmed.ncbi.nlm.nih.gov' in host:
            d['pmid']=parsed.path.strip('/') if parsed.path.strip('/').isdigit() else NA
        screening.append(d)
for q in searches:q['result_source_ids']=sorted(set(q['result_source_ids']))

gaps=[
 {'entity':'CXCL10','status':'await_full_text','description':'No directly extracted primary-human functional assertion. Loetscher1996 receptor abstract does not assign host/context to each functional experiment; Agostini lung-allograft candidate contains an accessible assay-method snippet but inspected result content was insufficient.'},
 {'entity':'CCL17','status':'primary_human_gap','description':'The retained human Hut78 response is a lymphoma-cell-line result. Primary human Th2 chemotaxis, donor context and receptor-blockade experiments remain unextracted.'},
 {'entity':'CCL13','status':'receptor_redundancy_gap','description':'Eosinophil CCR3 blockade does not establish exclusive receptor use. Garcia-Zepeda1996 CCR2/CCR3 and Stellato1997 CCR2 transfectant candidates await host-specific full-text extraction.'},
 {'entity':'CCL26','status':'mechanism_unresolved','description':'The late asthma-specific antagonist-insensitive component is not assigned to another receptor. Blockade adequacy, antibody dose and panel donor overlap remain incomplete.'},
 {'entity':'CCL3; CCL4','status':'preparation_context_gap','description':'1993 activation contrast and 1995 rapid-purification response are retained separately. They cannot establish a universal activation prerequisite; cohort overlap and exact purification details await full text.'},
 {'entity':'all eight assigned chemokines','status':'source_secretion_gap','description':'No new extracellular source-cell secretion assay was extracted. Tissue protein localization and transcript expression are not relabeled secretion.'},
 {'entity':'all','status':'bounded_access','description':'Entrez and PMC helper scripts failed with missing requests in both system and bundled Python; direct public shell retrieval hit sandbox DNS failure and stalled approval. No file was downloaded by that attempted call. Several browser opens returned challenges/403; only actual saved response access levels are claimed.'},
 {'entity':'all','status':'independence_unresolved','description':'Donor counts, ancestry, repeated-donor overlap and experimental precision were incompletely accessible. All cohort independence statuses remain unresolved; cell-line repeats are not donor replication.'}
]
pack=dict(sources=sources,cohorts=cohorts,assertions=assertions,searches=searches,gaps=gaps,synthesis='Bounded primary-source extraction for seven of eight assigned chemokines: 17 assertions, most provisional pending full methods. CCR3-sensitive eosinophil responses and disease/preparation-dependent contrasts are retained. Human tissue CCL22 localization is distinct from secretion; Hut78 chemotaxis is distinct from primary-cell evidence. CXCL10 remains a source-backed retrieval gap. No numerical prior, complete pathway, receptor exclusivity or human adjudication is claimed.')
